import java.io.DataInputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class Task939F {

    private static int n, k;
    private static int[] kbeg, kend;
    private static Map<String, Integer> memo;

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        n = sc.nextInt();
        k = sc.nextInt();
        kbeg = new int[k];
        kend = new int[k];
        for (int i = 0; i < k; i++) {
            kbeg[i] = sc.nextInt();
            kend[i] = sc.nextInt();
        }

        memo = new HashMap<>();
        int result = calcRotates(0, new int[]{0,0}, new int[]{0,0}, 0, 0, false, 0);
        if (result > 0) {
            System.out.println("Full");
            System.out.println(result);
        } else {
            System.out.println("Hungry");
        }
    }

    private static int calcRotates(int side, int[] tmin, int[] tmax,
                                   int noffset, int koffset, boolean isInterval, int numRotates) {
        if (tmin[0] > n || tmin[1] > n) return Integer.MAX_VALUE;
        if ((tmin[0] <= n && tmax[0] >= n) || (tmin[1] <= n && tmax[1] >= n)) {
            if ((tmax[0] < n && side == 1) || (tmax[1] < n && side == 0)) {
                return numRotates + 1;
            } else {
                return numRotates;
            }
        }
        if (koffset == k) return Integer.MAX_VALUE;

        String key = side + "|" + tmin[0] + "|" + tmin[1] + "|" + tmax[0] + "|" + tmax[1] + "|" + noffset + "|" + koffset + "|" + isInterval + "|" + numRotates;
        if (memo.containsKey(key)) return memo.get(key);

        int best = Integer.MAX_VALUE;

        if (isInterval) {
            if (kbeg[koffset] == kend[koffset]) {
                // no rotate
                best = Math.min(best, calcRotates(side, tmin, tmax, noffset, koffset + 1, false, numRotates));
                // rotate
                best = Math.min(best, calcRotates(1 - side, tmin, tmax, noffset, koffset + 1, false, numRotates + 1));
            } else {
                int diff = kend[koffset] - kbeg[koffset];
                // no rotate
                tmin[side] += diff;
                tmax[side] += diff;
                best = Math.min(best, calcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false, numRotates));
                tmin[side] -= diff;
                tmax[side] -= diff;

                // rotate once
                tmax[side] += diff;
                tmax[1 - side] += diff;
                best = Math.min(best, calcRotates(1 - side, tmin, tmax, kend[koffset], koffset + 1, false, numRotates + 1));
                tmax[side] -= diff;
                tmax[1 - side] -= diff;

                // rotate twice
                tmax[side] += diff;
                tmin[1 - side] += 1;
                tmax[1 - side] += diff - 1;
                best = Math.min(best, calcRotates(side, tmin, tmax, kend[koffset], koffset + 1, false, numRotates + 2));
                tmax[side] -= diff;
                tmin[1 - side] -= 1;
                tmax[1 - side] -= diff - 1;
            }
        } else {
            int diff = kbeg[koffset] - noffset;
            tmin[side] += diff;
            tmax[side] += diff;
            best = Math.min(best, calcRotates(side, tmin, tmax, kbeg[koffset], koffset, true, numRotates));
            tmin[side] -= diff;
            tmax[side] -= diff;
        }

        memo.put(key, best);
        return best;
    }

    // FastScanner unchanged from original
    public static class FastScanner {
        protected DataInputStream dataInputStream;
        protected byte[] buffer = new byte[0x10000];
        protected int bufferOffset;
        protected int bufferLength;
        protected boolean isEndOfFile;

        public FastScanner() throws IOException {
            dataInputStream = new DataInputStream(System.in);
            Read();
        }

        protected void Read() throws IOException {
            final int length = dataInputStream.read(buffer);
            if (length > 0) {
                bufferLength = length;
            } else {
                bufferLength = 0;
                isEndOfFile = true;
            }
            bufferOffset = 0;
        }

        protected byte nextByte() throws IOException {
            if (bufferOffset == bufferLength) {
                if (!isEndOfFile) Read();
                if (isEndOfFile) return 0;
            }
            return buffer[bufferOffset++];
        }

        public int nextInt() throws IOException {
            int a = 0;
            boolean isNegative = false;
            byte b = nextByte();
            while (b <= ' ') b = nextByte();
            if (b == '-') {
                isNegative = true;
                b = nextByte();
            }
            while (b > ' ') {
                a = a * 10 + (b - '0');
                b = nextByte();
            }
            return isNegative ? -a : a;
        }
    }
}
